window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"d8vsUIpTdcg","speaker":"Hilda Heine","role":"President","country":"Marshall Islands","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=d8vsUIpTdcg","date":"20260925","title":"🇲🇭 Marshall Islands - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1143,"words":2065,"counts":{"claims":28,"promises":2,"attacks":0},"topics":[{"topic":"Climate finance","share":0.1152,"seconds":132},{"topic":"Marshall Islands nuclear legacy","share":0.0789,"seconds":90},{"topic":"Multilateralism","share":0.0682,"seconds":78},{"topic":"UN resolution 2758","share":0.065,"seconds":74},{"topic":"Seabed mining","share":0.0633,"seconds":72},{"topic":"Marshall Islands energy","share":0.0632,"seconds":72},{"topic":"Sea level rise","share":0.0598,"seconds":68},{"topic":"Climate overshoot","share":0.0587,"seconds":67},{"topic":"Taiwan representation","share":0.0569,"seconds":65},{"topic":"Small island states","share":0.0565,"seconds":65},{"topic":"Ebeye sea wall","share":0.0548,"seconds":63},{"topic":"Law of the sea","share":0.0541,"seconds":62},{"topic":"Marshall Islands development","share":0.0541,"seconds":62},{"topic":"Nuclear testing","share":0.0535,"seconds":61},{"topic":"UN Security Council","share":0.0525,"seconds":60},{"topic":"UN reform","share":0.0455,"seconds":52}],"timeline":[[3,81,"Multilateralism"],[82,143,"Nuclear testing"],[145,235,"Marshall Islands nuclear legacy"],[236,303,"Climate overshoot"],[305,377,"Marshall Islands energy"],[379,442,"Climate finance"],[443,512,"Climate finance"],[514,582,"Sea level rise"],[583,645,"Ebeye sea wall"],[647,709,"Law of the sea"],[710,782,"Seabed mining"],[784,849,"Small island states"],[849,911,"Marshall Islands development"],[913,973,"UN Security Council"],[973,1038,"Taiwan representation"],[1039,1114,"UN resolution 2758"],[1114,1166,"UN reform"]],"stances":{"Multilateralism":"Hilda Heine argues that the credibility and effectiveness of multilateral institutions are imperative for small nations.","Nuclear testing":"Hilda Heine calls for the United Nations to deliver an apology and acknowledge the harm caused by nuclear weapons tests conducted on Marshall Islands territory between 1946 and 1958.","Marshall Islands nuclear legacy":"Hilda Heine states that the UN trusteeship was jeopardized by nuclear tests and that the lack of acknowledgement remains a moral failing, while noting the UN's role in authorizing further testing before contributing to the 1963 global ban.","Climate overshoot":"Hilda Heine calls for immediate global action to prevent or minimize exceeding the 1.5°C temperature limit agreed upon in Paris.","Marshall Islands energy":"Hilda Heine argues that accelerating the transition to renewable energy is logical and necessary, citing specific success in her country and calling for binding international regulations.","Climate finance":"Hilda Heine argues that countries like the Marshall Islands are suffering from fossil fuel transition delays and require immediate financial restitution for climate adaptation and loss.","Sea level rise":"Hilda Heine states that sea level rise is an immediate threat to low-lying atoll nations and asserts that international law now recognizes the rising seas rather than sinking islands as the cause of land loss.","Ebeye sea wall":"Hilda Heine describes the completed sea wall as a successful protective measure that cost $75 million and took over a decade, while emphasizing the urgent need for international partnerships to address rising sea levels.","Law of the sea":"Hilda Heine emphasizes that the law of the sea is a critical legal foundation for her nation's future and asserts that Pacific island leadership has historically defined multilateral milestones for oceans and fisheries.","Seabed mining":"Hilda Heine calls for a moratorium on seabed mining and emphasizes the need for science-driven regulations to protect global oceans.","Small island states":"Hilda Heine argues that small island developing states are ignored by the international community and that global geopolitical dynamics disproportionately threaten their security and economic stability.","Marshall Islands development":"Hilda Heine states that the Marshall Islands has linked national planning to SDG goals and is implementing direct assistance and income support for vulnerable groups.","UN Security Council":"Hilda Heine states that the Marshall Islands affirms its long-standing support for Japan and its G4 partners to achieve permanent membership on the UN Security Council.","Taiwan representation":"Hilda Heine asserts that Taiwan is an objective reality with a democratically elected government and argues for its substantive participation in UN meetings to ensure inclusivity and effectiveness.","UN resolution 2758":"Hilda Heine argues that UN General Assembly resolution 2758 should not be used as a legal pretext for coercion or war and warns against appeasing aggressors.","UN reform":"Hilda Heine argues that the United Nations must be revitalized to address global complexities and ensure no one is left behind."},"claims":[{"t":61,"quote":"The principles in the UN Charter, affirmed by each one of us taking our seat in this hall, are now tested not by argument, but by neglect or ill","topic":"Multilateralism","kind":"fact"},{"t":132,"quote":"impacts from the 67 nuclear weapons tested on our islands during our time as a UN strategic trust territory between 1946 and 1958","topic":"Nuclear testing","kind":"number"},{"t":186,"quote":"resolutions 1082 and 1493 in 1954 and 1956 respectively to effectively authorize further nuclear testing over the demands of our local leaders and many citizens.","topic":"Marshall Islands nuclear legacy","kind":"fact"},{"t":210,"quote":"the shock and tragedy of nuclear exposure in the Marshall Islands was a profound driver of the 1963 global ban on atmospheric testing of nuclear","topic":"Marshall Islands nuclear legacy","kind":"fact"},{"t":265,"quote":"scientists tell us overshooting the 1.5° temperature limit that we agreed in Paris is increasingly likely","topic":"Climate overshoot","kind":"fact"},{"t":318,"quote":"Technologies exist which provide secure, stable, zero-emissions energy.","topic":"Marshall Islands energy","kind":"fact"},{"t":329,"quote":"in the next 18 months renewable energy will cut fossil fuel use in our remote outer islands by 88%","topic":"Marshall Islands energy","kind":"number"},{"t":391,"quote":"We have developed our national adaptation plan working across ministries and with our people to determine how to make a safe Adapting is costly and takes time.","topic":"Climate finance","kind":"fact"},{"t":407,"quote":"Even as we've seen schools destroyed by rising seas, saltwater poisoning our wells, and disease outbreaks linked to environmental change.","topic":"Climate finance","kind":"fact"},{"t":443,"quote":"We have created homegrown institutions that are ready and willing to respond like the Pacific Resilience Facility, a regionally managed platform, and the Marshall Islands Adaptation and Resilient Trust Fund designed to enable donors to support our adaptation efforts.","topic":"Climate finance","kind":"fact"},{"t":476,"quote":"This week, the Marshall Islands convened the high ambition coalition, a diverse group of countries committed to a rigorous response to the climate crisis.","topic":"Climate finance","kind":"fact"},{"t":524,"quote":"This week's UN high-level meeting on sea level rise has helped achieve new understanding in international law.","topic":"Sea level rise","kind":"fact"},{"t":534,"quote":"It is the seas that are rising around us and not our islands, which are sinking.","topic":"Sea level rise","kind":"fact"},{"t":577,"quote":"we completed the Ebeye seawall and footpath last week.","topic":"Sea level rise","kind":"fact"},{"t":583,"quote":"1.8 km of oceanside built with support from the World Bank, the Green Climate Fund, and our own Engineered by Rising Seas, it now protects 8,400 people and critical energy infrastructure","topic":"Ebeye sea wall","kind":"fact"},{"t":621,"quote":"It cost $75 million, took 70,000 tons of rocks, took more than a decade to do, and it is just one island of over a thousand.","topic":"Ebeye sea wall","kind":"number"},{"t":656,"quote":"Even before we were a UN member, we fought closely both to participate in law UN law of the sea negotiations and to secure these rights","topic":"Law of the sea","kind":"fact"},{"t":667,"quote":"our Pacific island leadership, and that of all small island developing states, has defined every multilateral milestone for oceans and fisheries","topic":"Law of the sea","kind":"fact"},{"t":731,"quote":"The Marshall Islands join 45 nations seeking a moratorium on seabed mining.","topic":"Seabed mining","kind":"fact"},{"t":815,"quote":"As fuel and energy costs are rising beyond our ability to respond, impacts from bigger power plays halfway around the world are amplified tenfold in small remote economies.","topic":"Small island states","kind":"fact"},{"t":861,"quote":"Our national planning is now firmly linked to SDG goals and targets, and our actions proves our commitment.","topic":"Marshall Islands development","kind":"fact"},{"t":870,"quote":"We have developed direct assistance to vulnerable groups, including mothers and early childhood development, and we are also reaching out to our entire in-country population with quarterly supplemental income and improved access to digital finance tools.","topic":"Marshall Islands development","kind":"fact"},{"t":961,"quote":"the Marshall Islands affirms its long-standing support for Japan and its G4 partners to achieve permanent membership on the UN Security Council","topic":"UN Security Council","kind":"fact"},{"t":984,"quote":"Taiwan and its 23 million people are an objective reality","topic":"Taiwan representation","kind":"fact"},{"t":990,"quote":"only its democratically elected government can represent it","topic":"Taiwan representation","kind":"fact"},{"t":1039,"quote":"We all will experience pressure to accept a false narrative that UN General Assembly resolution 2758 somehow serves as a legal pretext under the UN Charter for coercion of or war, impairing freedom of navigation in one of the world's busiest shipping lanes.","topic":"UN resolution 2758","kind":"fact"},{"t":1106,"quote":"Two years ago, I concluded my statement by reciting an old Marshallese proverb, Wod in Kangal.","topic":"UN resolution 2758","kind":"self_credit"},{"t":1125,"quote":"Today, we are not only being called upon to revitalize this 81-year-old institution created from the ashes of global conflict","topic":"UN reform","kind":"fact"}],"promises":[{"t":682,"quote":"we will continue to do so","topic":"Law of the sea","kind":"promise"},{"t":769,"quote":"The Marshall Islands look forward to supporting its secretariat in a host nation committed to upholding the law of the sea as a matter of both principle and law in words and in actions.","topic":"Seabed mining","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":3,"topic":"Multilateralism","text":"The assembly will hear an address by her Excellency Hilda Heine, President of the Republic of the Marshall Islands. I request protocol to escort her Excellency and invite her to address the &gt;&gt; Mr. President, Mr. Secretary General, I ask every nation here, are we still willing to work together? The principles in the UN Charter, affirmed by each one of us taking our seat in this hall, are now tested not by argument, but by neglect or ill The credibility and effectiveness of multilateral institution is imperative for small nations."},{"t":82,"topic":"Nuclear testing","text":"It is past time to better turn the expressed in political political declarations and resolutions into not repetition. We speak from our own experience when we underscore the importance of acting together. An institution that takes collectively must also be accountable Mr. President, the United Nations is long overdue to reflect and renew the same spirit with which our Marshallese first came to the United Nation by delivering an apology and acknowledgement of the harm caused by impacts from the 67 nuclear weapons tested on our islands during our time as a UN strategic trust territory between 1946 and 1958."},{"t":145,"topic":"Marshall Islands nuclear legacy","text":"The sacred trust of the UN trusteeship to ensure our well-being was jeopardized by these tests and the lack of due acknowledgement remains a moral failing. For generations our families have testified to displacement illness, contamination and loss all of them impacts to our core human As our survivors would say and I quote, \"This is a song that has been sung far too many times.\" Unquote. It was in the same building that the UN Trusteeship Council sat in session and voted on resolutions 1082 and 1493 in 1954 and 1956 respectively to effectively authorize further nuclear testing over the demands of our local leaders and many citizens. The United Nations ultimately allowed the testing to continue but the shock and tragedy of nuclear exposure in the Marshall Islands was a profound driver of the 1963 global ban on atmospheric testing of nuclear We acknowledge the ongoing actions, dialogues and complex legacy of the UN's administering authority, the United But, the role of the United Nations cannot"},{"t":236,"topic":"Climate overshoot","text":"pass without without comment. For us and for fellow member states, this apology is an opportunity to reflect upon the past to bring healing and closure to the Marshallese people. We carry no long no larger agenda other than to ensure that the United Nations will do better. Mr. President, as we face a world in which scientists tell us overshooting the 1.5° temperature limit that we agreed in Paris is increasingly likely, we all need to wake up and act. Our focus now must be on preventing or minimizing the overshoot, shortening the time we spend above 1.5, and doing everything possible to fight our way back. As we gather in Tuvalu, Fiji, and Turkey for this year's climate pre-COP and COP, our response to the threat of overshoot must be overwhelming."},{"t":305,"topic":"Marshall Islands energy","text":"A much accelerated transition away from fossil fuels is the only logical Continued investment in fossil fuels is not only moral, but irrational. Technologies exist which provide secure, stable, zero-emissions energy. We are employing them in my own country, where in the next 18 months renewable energy will cut fossil fuel use in our remote outer islands by 88%, giving many access to electricity for the first time. We must do everything in our power to accelerate the develop uh deployment of renewables and to reduce fossil fuel production and consumption with equal This includes shipping shipping where we have the opportunity at the International Maritime Organization to adopt binding regulations that will place international shipping on a clear path to net zero by 2050 and generate the revenue required to ensure a just and equitable transition."},{"t":379,"topic":"Climate finance","text":"Mr. President, the denials and delays that have slowed the transition away from fossil fuels mean that countries like mine are already experiencing grave challenges. We have developed our national adaptation plan working across ministries and with our people to determine how to make a safe Adapting is costly and takes time. Even as we've seen schools destroyed by rising seas, saltwater poisoning our wells, and disease outbreaks linked to environmental change. This injustice must be addressed. Our communities deserve restitution. The Marshall Islands and vulnerable people everywhere need sufficient, timely, and accessible finance for adaptation and loss and damage. Those who have profited to the detriment of the many must pay."},{"t":443,"topic":"Climate finance","text":"We have created homegrown institutions that are ready and willing to respond like the Pacific Resilience Facility, a regionally managed platform, and the Marshall Islands Adaptation and Resilient Trust Fund designed to enable donors to support our adaptation efforts. Mr. President, the crisis has the power to divide us or to prove that we all remain willing to achieve common goals. This week, the Marshall Islands convened the high ambition coalition, a diverse group of countries committed to a rigorous response to the climate crisis. We are united in the view that the best available science must lead these the decisions we make, the importance of a 1.5° C temperature limit, an urgent transition away from fossil fuels, and the need for adequate and accessible climate finance, especially for adaptation and loss and damage."},{"t":514,"topic":"Sea level rise","text":"Mr. President, as a low-lying atoll nation with no higher ground, sea level rise is is an immediate and stark This week's UN high-level meeting on sea level rise has helped achieve new understanding in international law. It is the seas that are rising around us and not our islands, which are sinking. Our boundaries and baselines of today, the political footprint on the map, will endure in the face of aggressive sea level rise scenarios. Our collective stability and security as Pacific Islands Forum members and as a UN member state will be now better addressed. As an atoll nation, our tide gauge is proof enough that far more action is And we are acting. Confronted with rising seas on our most vulnerable shorelines, we completed the Ebeye seawall and footpath last week."},{"t":583,"topic":"Ebeye sea wall","text":"1.8 km of oceanside built with support from the World Bank, the Green Climate Fund, and our own Engineered by Rising Seas, it now protects 8,400 people and critical energy infrastructure, reduces annual coastal flooding losses, and anchors resilient future development on Ebeye, including schools, housing, and the proposed new hospital, while providing a safe public space that strengthens community well-being. It cost $75 million, took 70,000 tons of rocks, took more than a decade to do, and it is just one island of over a thousand. We are taking action, and we urgently need strengthened partnership to better protect our islands before sea level rise overtakes us."},{"t":647,"topic":"Law of the sea","text":"Mr. President, my nation underscores the importance of the law of the sea as a key legal pillar of our future. Even before we were a UN member, we fought closely both to participate in law UN law of the sea negotiations and to secure these rights in our Pacific island leadership, and that of all small island developing states, has defined every multilateral milestone for oceans and fisheries, and we will continue to do so. As an ocean people, the consequences of getting it wrong are not from distant impacts, but adjacent to our waters particularly in the North Pacific both within the International Seabed and unilateral actions. the people and voices of Micronesia must be heard."},{"t":710,"topic":"Seabed mining","text":"We are joined by Guam, Northern Marianas, Federated States of Micronesia, and Palau in expressing our alarm at seabed mining actions where the decisions are made before impacts are well understood and where adequate safeguards remain The Marshall Islands join 45 nations seeking a moratorium on seabed mining. Responsible and science-driven regulations need to be in place. Going on guesswork for global oceans is beyond dangerous. There are no do-overs. The Marshall Islands look forward to the first Conference of Parties to the Biodiversity Beyond National to work across silos to advance IC's We urge wide ratification of the The Marshall Islands look forward to supporting its secretariat in a host nation committed to upholding the law of the sea as a matter of both principle and law in words and in actions."},{"t":784,"topic":"Small island states","text":"Mr. President, too often the word geopolitics is considered to refer only to the whims of superpowers and not the reality of our fragile place between them. As a region of vulnerable island nations, we readily define our own security priorities and they deeply cut across every sector, placing a safe future for our youngest beyond grasp. As fuel and energy costs are rising beyond our ability to respond, impacts from bigger power plays halfway around the world are amplified tenfold in small remote economies. The international community is not listening closely to small island developing states and it is not responding fast enough. Too often, the purported solutions for island nations don't seem to know the Mr."},{"t":849,"topic":"Marshall Islands development","text":"President, the Marshall Islands faces complex challenges in tackling the but we committed with all of our efforts to ensure no one is left behind. Our national planning is now firmly linked to SDG goals and targets, and our actions proves our commitment. We have developed direct assistance to vulnerable groups, including mothers and early childhood development, and we are also reaching out to our entire in-country population with quarterly supplemental income and improved access to digital finance tools. Our aspirations must be better matched by partnership and island-scale investment and policy innovation. I must underscore the dire need for data capacity support to measure progress and effectiveness for small islands developing states."},{"t":913,"topic":"UN Security Council","text":"If we cannot assess the assess the SDGs, we cannot correct course. Mr. President, the Marshall Islands affirms the region Pacific Islands Forum communicate position regarding West including the 2018 invitation by to the UN Human Rights Commissioner. Further, the Marshall Islands strongly welcomes recent calls for a ministerial summit between ASEAN and the Pacific Islands Forum to take forward our 2020 2023 agreement. Our two regions can stand united as neighbors and close friends. The Marshall Islands affirms its long-standing support for Japan and its G4 partners to achieve permanent membership on the UN Security Council. Mr."},{"t":973,"topic":"Taiwan representation","text":"President, the Marshall Islands expresses its grave concern over increased efforts to spread spread dangerous disinformation in these halls. Taiwan and its 23 million people are an objective reality and only its democratically elected government can represent it. Appropriate ways must be found for Taiwan's substantive participation in UN meetings if the UN is to be truly inclusive and effective. In years to come, every nation in this hall may be told that the question or coercion upon Taiwan is an internal somehow justified by an ancient UN seating chart resolution. A resolution which doesn't even reference Taiwan. In years to come, we may all be told that it's futile for a small nations to resist a larger one and that might makes right regardless of the rulebook."},{"t":1039,"topic":"UN resolution 2758","text":"We all will experience pressure to accept a false narrative that UN General Assembly resolution 2758 somehow serves as a legal pretext under the UN Charter for coercion of or war, impairing freedom of navigation in one of the world's busiest shipping lanes. We will be asked politely and impolitely to turn a blind eye and look away. It is vital that every nation here, including our close partners in our own region, know that know that appeasement never satisfied satisfies an aggressor's wider agenda. And one taste is never enough. How the UN addresses this very real security dilemma will be a test of its strength and relevance. Excellencies, the Marshall Islands stands firm in investing ourselves in this multilateral institution with clear sight of its frustrations and grave Two years ago, I concluded my statement by reciting an old Marshallese proverb, Wod in Kangal."},{"t":1114,"topic":"UN reform","text":"Wod in Kangal. It describes the coral reef where different species of fish congregate to feed and seek shelter. Today, we are not only being called upon to revitalize this 81-year-old institution created from the ashes of global conflict, but we are being challenged to address the complexities of a rapidly changing The United Nations must continue to serve as our primary Wod in Kangal to ensure that no one is left behind. Thank you. Kommol tata. &gt;&gt; On behalf of the Assembly, I wish to thank the President of the Republic of the Marshall Islands."}],"compare":[{"topic":"Climate Change","share":0.2336,"mean":0.0418,"rank":4,"others":77},{"topic":"Taiwan","share":0.1219,"mean":0.0022,"rank":1,"others":7},{"topic":"UN & its reform","share":0.0981,"mean":0.2053,"rank":144,"others":170},{"topic":"International Law & Order","share":0.0682,"mean":0.0604,"rank":67,"others":102},{"topic":"Ocean Governance","share":0.0633,"mean":0.0065,"rank":10,"others":16},{"topic":"Small states","share":0.0565,"mean":0.0022,"rank":6,"others":6},{"topic":"Maritime Security","share":0.0548,"mean":0.0044,"rank":8,"others":9},{"topic":"Maritime Law","share":0.0541,"mean":0.0016,"rank":5,"others":4}]};
